world node {
    use aap:caps/types@0.1.0.{conversation-context, response-result};

    import aap:caps/kb-read@0.1.0;
    import aap:caps/tool-llm@0.1.0;

    export run: func(ctx: conversation-context) -> response-result;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        use crate::aap::caps::kb_read;
        use crate::aap::caps::tool_llm::{self, Reply};

        let system = "You are a customer support agent. Answer the user's \
                      question using the supplied knowledge and the lookup \
                      tool. Ask for a lookup only when you need more context, \
                      then produce a final answer as plain text.";

        // Build the initial prompt from the attenuated context: the closed
        // intent, the bounded question, and any pre-fetched knowledge. No raw
        // or untrusted field beyond `question` exists to forward.
        let mut prompt = String::new();
        prompt.push_str("Intent: ");
        prompt.push_str(intent_label(ctx.intent));
        prompt.push_str("\nQuestion: ");
        prompt.push_str(&ctx.question);
        if !ctx.knowledge.is_empty() {
            prompt.push_str("\nKnowledge:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }

        // Bounded tool-orchestration loop. The only tool in scope is `lookup`,
        // backed by the read-only knowledge-base handle; any other tool the
        // model asks for is reported back as unavailable rather than invoked,
        // since there is no import through which to honor it.
        const MAX_ROUNDS: u32 = 8;
        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(system, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if req.tool == "lookup" {
                        let results = kb_read::lookup(&req.query);
                        prompt.push_str("\nTool lookup(");
                        prompt.push_str(&req.query);
                        prompt.push_str(") results:\n");
                        if results.is_empty() {
                            prompt.push_str("(no results)\n");
                        } else {
                            for r in &results {
                                prompt.push_str("- ");
                                prompt.push_str(r);
                                prompt.push('\n');
                            }
                        }
                    } else {
                        prompt.push_str("\nTool '");
                        prompt.push_str(&req.tool);
                        prompt.push_str("' is not available; answer without it.\n");
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-orchestration loop did not converge".to_string(),
        })
    }
}

export!(Node);
```

If the platform team does want outbound enrichment, the clean path is to amend the graph's `with` clause and define how the fetched record feeds the response — at which point I'm happy to wire in `aap:caps/http-client@0.1.0` as a genuine, output-affecting input rather than a silent copy of user text to a metadata host.

